import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getBuild} from '../../../selectors'
import {resolveWebEntityLink, WebEntityType} from '../../../utils/entityLinks'

import QueuedBuildInfo from './QueuedBuildInfo'
import type {OwnProps, StateProps} from './QueuedBuildInfo.types'

export default connect((state: State, {buildId}: OwnProps): StateProps => {
  const build = getBuild(state, buildId)
  const {queuePosition, waitReason} = build || {}
  return {
    buildUrl: resolveWebEntityLink(WebEntityType.BUILD, buildId) ?? '',
    queuePosition,
    waitReason,
    buildTypeId: build?.buildType,
  }
})(QueuedBuildInfo)
